mapper.insert:
insert into point_accu_mst(
   point_event_key
  ,order_no
  ,accu_date
  ,expire_date
  ,user_no
  ,accu_point
  ,accu_cancel_yn
  ,balance_point
  ,org_point_key
)
values(
   #{pointEventKey}
  ,#{orderNo}
  ,CURRENT_DATE()
  ,DATEADD('DAY', #{expireDays}, CURRENT_DATE())
  ,#{userNo}
  ,#{accuPoint}
  ,#{accuCancelYn}
  ,#{balancePoint}
  ,ifnull(#{orgPointKey},0)
)

mapper.select:
select a.point_key ,a.point_event_key ,a.order_no ,a.accu_date ,a.expire_date ,a.user_no ,a.accu_point ,a.accu_cancel_yn ,a.balance_point ,b.point_accu_type from point_accu_mst a inner join point_event_mst b on a.point_event_key = b.point_event_key
and a.user_no = #{userNo}
and a.point_key = #{pointKey}
and a.order_no = #{orderNo}
and a.accu_cancel_yn = 'N' and a.balance_point > 0 order by point_accu_type desc, expire_date

mapper.update:
update point_accu_mst set
        balance_point = balance_point - #{usePoint}
where   point_key = #{pointKey}
  and   accu_cancel_yn = 'N'
  and   balance_point >= #{usePoint}

update point_accu_mst set
    balance_point = balance_point + #{usePoint}
where   point_key = #{pointKey}
  and   accu_cancel_yn = 'N'
  and   accu_point >= (balance_point + #{usePoint})

